<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Curia\BoundedExecutionAuthorizationService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:curia:authorize-bounded-execution',description:'Authorize one exact internal execution input for one deployed Manifestation.')]
final class CuriaAuthorizeBoundedExecutionCommand extends Command{public function __construct(private readonly BoundedExecutionAuthorizationService$s){parent::__construct();}protected function configure():void{$this->addArgument('transition-id',InputArgument::REQUIRED)->addArgument('seneschal-binding-id',InputArgument::REQUIRED)->addArgument('target-url',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->authorize((string)$i->getArgument('transition-id'),(string)$i->getArgument('seneschal-binding-id'),['target_url'=>(string)$i->getArgument('target-url')]);}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln($i->getOption('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>BOUNDED_EXECUTION_AUTHORIZED</info> '.$r['authorization_id']);return self::SUCCESS;}}
